with RecentInventory as (select * from inventory where product_id = 7 and product_id in (5, 6, 8, 10) and last_restock between '2023-03-19' and '2025-07-01'), product_id_summary as (select product_id, case when quantity >= 261 then 'high' when quantity >= 66 then 'mid' else 'low' end quantity_bucket, max(quantity) max_quantity from RecentInventory group by product_id, case when quantity >= 261 then 'high' when quantity >= 66 then 'mid' else 'low' end) select product_id, quantity_bucket, max_quantity from product_id_summary order by quantity_bucket
